const input = $input.first().json;
let text = '';
if (input.choices && input.choices[0]) {
  text = input.choices[0].message.content;
} else { text = JSON.stringify(input); }

let cleaned = text.replace(/```json|```/g, '').trim();

// Fix literal newlines inside JSON string values by escaping them
cleaned = cleaned.replace(/"((?:[^"\\]|\\.)*)"/g, function(match, group) {
  const fixed = group.replace(/\n/g, '\\n').replace(/\r/g, '\\r');
  return '"' + fixed + '"';
});

const parsed = JSON.parse(cleaned);
return [{ json: parsed }];

