parameters.jsCode:
const items = $input.all();

let summary = '';
const parsed = [];

for (const item of items) {
let d = item.json;
if (typeof d.result === 'string') {
try { d = JSON.parse(d.result); } catch(e) {}
}
parsed.push(d);
}

const currentAction = $('Code in JavaScript').first().json.action || '';
const alsoEmail = $('Code in JavaScript').first().json.also_email === true;

function getOriginalDataField(fieldName) {
try {
const node2 = $('Code in JavaScript2').first();
if (node2 && node2.json && node2.json.originalData) {
const parsedOriginal = JSON.parse(node2.json.originalData);
return parsedOriginal[fieldName] || '';
}
return '';
} catch (e) {
return '';
}
}

let calendarItem = null;
for (let i = 0; i < parsed.length; i++) {
if (parsed[i] && parsed[i].start) {
calendarItem = parsed[i];
break;
}
}

const first = calendarItem || parsed[0];

if (first && first.start && currentAction === 'get') {
summary = 'Here are your upcoming events:\n\n';
for (const d of parsed) {
const startRaw = (d.start && d.start.dateTime) || (d.start && d.start.date) || '';
const endRaw = (d.end && d.end.dateTime) || (d.end && d.end.date) || '';
const startDate = new Date(startRaw).toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Africa/Lagos' });
const startTime = new Date(startRaw).toLocaleTimeString('en-GB', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'Africa/Lagos' });
const endTime = new Date(endRaw).toLocaleTimeString('en-GB', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'Africa/Lagos' });
const title = d.summary || 'Untitled Event';
const description = d.description || '';
const location = d.location || '';
const meetLink = d.hangoutLink || '';

summary += '*' + title + '*\n';
summary += 'Date: ' + startDate + '\n';
summary += 'Time: ' + startTime + ' - ' + endTime + '\n';
if (description) {
summary += 'Description: ' + description + '\n';
}
if (location) {
summary += 'Location: ' + location + '\n';
}
if (meetLink) {
summary += '[Join Meeting](' + meetLink + ')\n';
}
summary += '\n';
}
} else if (first && first.start && (currentAction === 'create' || currentAction === 'create_with_attendees')) {
const title = first.summary || $('Code in JavaScript').first().json.title || 'Meeting';
const start = (first.start && first.start.dateTime) || (first.start && first.start.date) || '';
const date = new Date(start).toLocaleString('en-NG', { timeZone: 'Africa/Lagos' });
const link = first.htmlLink || '';
const meetLink = first.hangoutLink || '';
summary = title + ' has been scheduled for ' + date + ' successfully!';
if (meetLink) {
summary += '\n[Join Meeting](' + meetLink + ')';
}
if (link) {
summary += ' | [View Event](' + link + ')';
}
if (alsoEmail) {
summary += '\n\nThe attendee has also been emailed the meeting details.';
}
} else if (first && first.start && currentAction === 'reschedule') {
const title = first.summary || $('Code in JavaScript').first().json.title || 'Meeting';
const start = (first.start && first.start.dateTime) || (first.start && first.start.date) || '';
const date = new Date(start).toLocaleString('en-NG', { timeZone: 'Africa/Lagos' });
const link = first.htmlLink || '';
const meetLink = first.hangoutLink || '';
summary = title + ' has been rescheduled to ' + date + ' successfully!';
if (meetLink) {
summary += '\n[Join Meeting](' + meetLink + ')';
}
if (link) {
summary += ' | [View Event](' + link + ')';
}
} else if (first && first.start) {
summary = 'Calendar action completed successfully!';
} else if (first && first.resourceName && currentAction === 'save') {
const name = $('Code in JavaScript').first().json.name || (($('Code in JavaScript').first().json.firstName || '') + ' ' + ($('Code in JavaScript').first().json.lastName || '')).trim() || 'Contact';
summary = name + "'s contact has been saved successfully!";
} else if (first && first.resourceName && currentAction === 'update') {
const name = $('Code in JavaScript').first().json.name || 'Contact';
summary = name + "'s contact has been updated successfully!";
} else if (first && first.resourceName && currentAction === 'retrieve') {
const searchName = ($('Code in JavaScript').first().json.contact_name || $('Code in JavaScript').first().json.name || '').toLowerCase();
const filtered = parsed.filter(function(d) {
const name = (d.names && d.names.displayName) || '';
if (!searchName) return true;
return name.toLowerCase().indexOf(searchName) !== -1;
});
if (filtered.length === 0) {
summary = 'No contact found matching that name.';
} else {
for (const d of filtered) {
const name = (d.names && d.names.displayName) || 'Unknown';
const email = (d.emailAddresses && d.emailAddresses.work && d.emailAddresses.work[0]) || (d.emailAddresses && d.emailAddresses.home && d.emailAddresses.home[0]) || 'No email';
const phone = (d.phoneNumbers && d.phoneNumbers.work && d.phoneNumbers.work[0]) || (d.phoneNumbers && d.phoneNumbers.home && d.phoneNumbers.home[0]) || 'No phone';
summary = 'Here is ' + name + "'s contact details:\n";
summary += '• Email: ' + email + '\n';
summary += '• Phone: ' + phone + '\n';
}
}
} else if (first && first.threadId && currentAction === 'get') {
const emailLimit = $('Code in JavaScript').first().json.limit || 5;
const emailsToShow = parsed.slice(0, emailLimit);
summary = 'Here are your ' + emailLimit + ' most recent emails:\n';
for (const d of emailsToShow) {
const subject = d.subject || '(no subject)';
const from = (d.headers && d.headers.from) || d.from || 'Unknown sender';
summary += '• ' + subject + ' - ' + from + '\n';
}
} else if (first && first.threadId && currentAction === 'send') {
const to = $('Code in JavaScript').first().json.to || $('Code in JavaScript').first().json.contact_name || 'recipient';
summary = 'Email sent to ' + to + ' successfully!';
} else if ((first && first.threadId && currentAction === 'draft') || (first && first.id && first.message && currentAction === 'draft')) {
const to = $('Code in JavaScript').first().json.to || $('Code in JavaScript').first().json.contact_name || 'recipient';
summary = 'Email draft to ' + to + ' saved successfully!';
} else if (first && first.threadId && currentAction === 'reply') {
summary = 'Reply sent successfully!';
} else if (first && first.threadId) {
summary = 'Email action completed successfully!';
} else if (first && first.success === true && currentAction === 'delete') {
const searchTerm = getOriginalDataField('search_term');
const eventTitle = getOriginalDataField('event_title');
if (searchTerm) {
summary = 'The email from ' + searchTerm + ' has been deleted successfully!';
} else if (eventTitle) {
summary = eventTitle + ' has been deleted successfully!';
} else {
const name = $('Code in JavaScript').first().json.name || $('Code in JavaScript').first().json.contact_name || 'Contact';
summary = name + "'s contact has been deleted successfully!";
}
} else if (first && first.success === true) {
const action = $('Code in JavaScript').first().json.action || '';
const name = $('Code in JavaScript').first().json.name || $('Code in JavaScript').first().json.contact_name || 'Contact';
if (action === 'delete') {
summary = name + "'s contact has been deleted successfully!";
} else if (action === 'update') {
summary = name + "'s contact has been updated successfully!";
} else {
summary = 'Action completed successfully!';
}
} else {
summary = 'Action completed successfully!';
}

return [{ json: { summary } }];

const inputData = $input.all();
const originalData = JSON.parse($('Code in JavaScript2').first().json.originalData || '{}');

const result = {};
const keys = Object.keys(originalData);
for (let i = 0; i < keys.length; i++) {
result[keys[i]] = originalData[keys[i]];
}

const stopWords = ['the', 'a', 'an', 'meeting', 'event', 'call', 'session'];

function getSignificantWords(str) {
return str.toLowerCase().split(/\s+/).filter(function(w) {
return w.length > 0 && stopWords.indexOf(w) === -1;
});
}

function wordsOverlap(str1, str2) {
const words1 = getSignificantWords(str1);
const words2 = getSignificantWords(str2);
if (words1.length === 0 || words2.length === 0) return false;
for (let i = 0; i < words1.length; i++) {
if (words2.indexOf(words1[i]) !== -1) {
return true;
}
}
return false;
}

if (originalData.contact_name || originalData.attendee_name) {
const searchName = (originalData.contact_name || originalData.attendee_name || '').toLowerCase();
let email = '';
let found = false;
for (let i = 0; i < inputData.length; i++) {
if (found) { continue; }
const item = inputData[i].json;
const name = (item.names && item.names.displayName) || '';
if (name.toLowerCase().indexOf(searchName) !== -1) {
email = (item.emailAddresses && item.emailAddresses.work && item.emailAddresses.work[0]) ||
(item.emailAddresses && item.emailAddresses.home && item.emailAddresses.home[0]) || '';
found = true;
}
}
if (originalData.contact_name) {
result.to = email;
delete result.contact_name;
}
if (originalData.attendee_name) {
result.attendees = email;
delete result.attendee_name;
}
}

if (originalData.event_title) {
const eventTitle = originalData.event_title.toLowerCase();
let eventId = '';
let found = false;
for (let i = 0; i < inputData.length; i++) {
if (found) { continue; }
const item = inputData[i].json;
const title = (item.summary || '').toLowerCase();
if (title.indexOf(eventTitle) !== -1 || eventTitle.indexOf(title) !== -1 || wordsOverlap(title, eventTitle)) {
eventId = item.id || '';
found = true;
}
}
result.eventId = eventId;
delete result.event_title;
}

if (originalData.search_term) {
const searchTerm = originalData.search_term.toLowerCase();
let messageId = '';
let threadId = '';
let found = false;
for (let i = 0; i < inputData.length; i++) {
if (found) { continue; }
const item = inputData[i].json;
const subject = (item.subject || '').toLowerCase();
const from = ((item.headers && item.headers.from) || '').toLowerCase();
if (subject.indexOf(searchTerm) !== -1 || from.indexOf(searchTerm) !== -1) {
messageId = item.id || '';
threadId = item.threadId || '';
found = true;
}
}
result.messageId = messageId;
result.threadId = threadId;
delete result.search_term;
}

return [{ json: result }];

try {
const data = $input.all()[0] ? $input.all()[0].json : {};

const searchName = data.contact_name || data.attendee_name || '';
const eventTitle = data.event_title || '';
const searchTerm = data.search_term || '';

// Contact lookup needed
if (searchName) {
return [{ json: {
agent: 'contact',
action: 'retrieve',
name: searchName,
originalData: JSON.stringify(data)
} }];
}

// Calendar event lookup needed
if (eventTitle) {
return [{ json: {
agent: 'calendar',
action: 'get',
startTime: new Date().toISOString(),
endTime: new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString(),
originalData: JSON.stringify(data)
} }];
}

// Email lookup needed
if (searchTerm) {
return [{ json: {
agent: 'email',
action: 'get',
startTime: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString(),
originalData: JSON.stringify(data)
} }];
}

return [{ json: data }];
} catch(e) {
return [{ json: { error: e.message } }];
}

const calendarResult = $input.first().json;
const originalData = $('Code in JavaScript').first().json;

const title = calendarResult.summary || originalData.title || 'Meeting';
const start = (calendarResult.start && calendarResult.start.dateTime) || '';
const dateObj = new Date(start);
const formattedDate = dateObj.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Africa/Lagos' });
const formattedTime = dateObj.toLocaleTimeString('en-GB', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: 'Africa/Lagos' });

const meetLink = calendarResult.hangoutLink || '';
const eventLink = calendarResult.htmlLink || '';

let attendeeEmail = '';
if (calendarResult.attendees && calendarResult.attendees.length > 0) {
attendeeEmail = calendarResult.attendees[0].email || '';
}

const fullName = originalData.attendee_name || 'there';
const firstName = fullName.split(' ')[0];

let body = '<p>Hi ' + firstName + ',</p>';
body += '<p>You have been invited to <strong>' + title + '</strong> scheduled for ' + formattedDate + ' at ' + formattedTime + '</p>';

if (meetLink) {
body += '<p><a href="' + meetLink + '">Join via Google Meet</a></p>';
}
if (eventLink) {
body += '<p><a href="' + eventLink + '">View in Calendar</a></p>';
}

body += '<p>Looking forward to it!</p>';
body += '<p>Best regards,<br>Esther</p>';

return [{ json: {
agent: 'email',
action: 'send',
to: attendeeEmail,
subject: 'Meeting Invitation: ' + title,
body: body
} }];

const emailResult = $input.first().json;
const calendarResult = $('Email Attendee').first().json;

return [
{ json: calendarResult },
{ json: emailResult }
];
